module webcrypto

import encoding.hex
import webidl

// Exact upstream WPT sign_verify/mldsa_vectors.js fixtures.
struct MldsaSourceFixture {
	name          string
	pkcs8_hex     string
	spki_hex      string
	signature_hex string
}

const mldsa_message_hex = '4d4c2d4453412074657374206d65737361676520666f72207369676e696e6720616e6420766572696669636174696f6e2e205468697320697320612074657374206f66204d4c2d44534120696d706c656d656e746174696f6e2e'
const mldsa_source_fixtures = [
	MldsaSourceFixture{ name: 'ML-DSA-44', pkcs8_hex: '3034020100300b06096086480165030403110422802099155f633096da7cbe087a8948b84f767b10f901c823c240b1dd2bc87005c93e', spki_hex: '', signature_hex: '' },
	MldsaSourceFixture{ name: 'ML-DSA-65', pkcs8_hex: '3034020100300b06096086480165030403120422802084a4894b7b46a4b2039cce10c31a85bab0c36630fe231d42671143982607828b', spki_hex: '', signature_hex: '' },
	MldsaSourceFixture{ name: 'ML-DSA-87', pkcs8_hex: '3034020100300b060960864801650304031304228020a1506d914c6d658c7527e43397dd6d4c25f6a47974335a4cd03bfe6983441251', spki_hex: '', signature_hex: '' },
]

fn test_mldsa_all_upstream_vectors_and_native_context_signing() {
	subtle := SubtleCrypto.create()
	message := hex.decode(mldsa_message_hex)!
	for fixture in mldsa_source_fixtures {
		private_key := subtle.import_key(.pkcs8, hex.decode(fixture.pkcs8_hex)!, fixture.name, true, [.sign], '')!
		public_key := subtle.import_key(.spki, hex.decode(fixture.spki_hex)!, fixture.name, true, [.verify], '')!
		assert subtle.verify(fixture.name, public_key, hex.decode(fixture.signature_hex)!, message)!
		assert !subtle.verify(fixture.name, public_key, hex.decode(fixture.signature_hex)!, [u8(1)])!
		signature := subtle.sign(fixture.name, private_key, message)!
		_, _, size := mldsa_sizes(fixture.name)!
		assert signature.len == size
		assert subtle.verify(fixture.name, public_key, signature, message)!
		contextual := Ed448Params{ name: fixture.name, context: 'foo'.bytes() }
		context_signature := subtle.sign(contextual, private_key, message)!
		assert subtle.verify(contextual, public_key, context_signature, message)!
		assert !subtle.verify(fixture.name, public_key, context_signature, message)!
		assert subtle.export_key(.pkcs8, private_key)!.hex() == fixture.pkcs8_hex
		assert subtle.export_key(.spki, public_key)!.hex() == fixture.spki_hex
		private_handle := private_key.internal_handle() as MldsaPrivateKeyHandle
		public_handle := public_key.internal_handle() as MldsaPublicKeyHandle
		assert private_handle.public_key == public_handle.public_key
		seed_key := subtle.import_key(.raw_seed, private_handle.seed, fixture.name, true, [.sign], '')!
		assert (seed_key.internal_handle() as MldsaPrivateKeyHandle).private_key == private_handle.private_key
		assert subtle.export_key(.raw_seed, seed_key)! == private_handle.seed
		raw_key := subtle.import_key(.raw_public, public_handle.public_key, fixture.name, true, [.verify], '')!
		assert subtle.export_key(.raw_public, raw_key)! == public_handle.public_key
		jwk := subtle.export_jwk(private_key)!
		assert jwk.kty? == 'AKP' && jwk.alg? == fixture.name
		assert jwk.pub_? == base64url_encode(private_handle.public_key)
		assert jwk.priv? == base64url_encode(private_handle.seed)
		jwk_key := subtle.import_jwk(jwk, fixture.name, true, [.sign], '')!
		assert (jwk_key.internal_handle() as MldsaPrivateKeyHandle).private_key == private_handle.private_key
		public_jwk := subtle.export_jwk(public_key)!
		assert public_jwk.priv == none
		assert subtle.import_jwk(public_jwk, fixture.name, true, [.verify], '')!.handle() == public_handle.public_key
		expanded := okp_der_value(0x24, okp_der_value(0x04, private_handle.private_key))
		expanded_key := subtle.import_key(.pkcs8, wrap_no_parameter_key_info(mldsa_oid_bytes(fixture.name)!, expanded, true), fixture.name, true, [.sign], '')!
		assert (expanded_key.internal_handle() as MldsaPrivateKeyHandle).seed.len == 0
		mut seed_scope := okp_der_value(0x04, private_handle.seed)
		seed_scope << okp_der_value(0x24, expanded)
		both := okp_der_value(0x30, okp_der_value(0x24, seed_scope))
		both_key := subtle.import_key(.pkcs8, wrap_no_parameter_key_info(mldsa_oid_bytes(fixture.name)!, both, true), fixture.name, true, [.sign], '')!
		assert (both_key.internal_handle() as MldsaPrivateKeyHandle).private_key == private_handle.private_key
	}
}

fn test_mldsa_generation_and_source_errors_and_jwk_conditions() {
	subtle := SubtleCrypto.create()
	for name in ['ML-DSA-44', 'ML-DSA-65', 'ML-DSA-87'] {
		generated := subtle.generate_key(AlgorithmParams{ name: name }, false, [
			.verify,
			.sign,
			.sign,
		])!
		pair := generated.pair or { panic('pair') }
		assert pair.public_key.extractable && !pair.private_key.extractable
		assert pair.public_key.usages == [KeyUsage.verify] && pair.private_key.usages == [
			KeyUsage.sign,
		]
		assert subtle.verify(name, pair.public_key, subtle.sign(name, pair.private_key, [])!, [])!
		if _ := subtle.generate_key(AlgorithmParams{ name: name }, true, [.verify]) {
			assert false
		} else {
			assert err.msg() == 'SyntaxError: usages must not be empty'
		}
	}
	fixture := mldsa_source_fixtures[0]
	private_key := subtle.import_key(.pkcs8, hex.decode(fixture.pkcs8_hex)!, fixture.name, true, [.sign], '')!
	public_key := subtle.import_key(.spki, hex.decode(fixture.spki_hex)!, fixture.name, true, [.verify], '')!
	if _ := MLDSA.create().sign(Ed448Params{ name: fixture.name }, public_key, []) {
		assert false
	} else {
		assert err.msg() == 'InvalidAccessError: Key is not a private key'
	}
	if _ := MLDSA.create().verify(Ed448Params{ name: fixture.name }, private_key, [], []) {
		assert false
	} else {
		assert err.msg() == 'InvalidAccessError: Key is not a public key'
	}
	if _ := subtle.sign(Ed448Params{ name: fixture.name, context: []u8{len: 256} }, private_key, []) {
		assert false
	} else {
		assert err.msg() == 'OperationError: Context is too long'
	}
	if _ := subtle.import_key(.raw_seed, [], fixture.name, true, [.verify], '') {
		assert false
	} else {
		assert err.msg() == "SyntaxError: Invalid key usage 'verify'"
	}
	if _ := subtle.import_key(.raw_seed, [], fixture.name, true, [.sign], '') {
		assert false
	} else {
		assert err.msg() == 'DataError: Seed must be 256 bits long'
	}
	if _ := subtle.import_key(.raw, [], fixture.name, true, [.verify], '') {
		assert false
	} else {
		assert err.msg() == 'NotSupportedError: Invalid key format'
	}
	jwk := subtle.export_jwk(private_key)!
	if _ := subtle.import_jwk(JsonWebKey{ ...jwk, pub_: 'AA' }, fixture.name, true, [.sign], '') {
		assert false
	} else {
		assert err.msg() == 'DataError: JsonWebKey public key does not match'
	}
	if _ := subtle.import_jwk(JsonWebKey{ ...jwk, use: 'enc', key_ops: none }, fixture.name, true, [.sign], '') {
		assert false
	} else {
		assert err.msg() == 'DataError: Invalid usage type'
	}
	assert subtle.import_jwk(JsonWebKey{ ...jwk, use: 'sig' }, fixture.name, true, [.sign], '')!.type_ == .private_key
	if _ := subtle.import_jwk(JsonWebKey{ ...jwk, ext: false }, fixture.name, true, [.sign], '') {
		assert false
	} else {
		assert err.msg() == 'DataError: Invalid ext field'
	}
	if _ := subtle.import_jwk(JsonWebKey{ ...jwk, key_ops: ['verify'] }, fixture.name, true, [.sign], '') {
		assert false
	} else {
		assert err.msg().starts_with('DataError:')
	}
	primitive := wrap_no_parameter_key_info(mldsa_oid_bytes(fixture.name)!, okp_der_value(0x04, []u8{len: 2560}), true)
	if _ := subtle.import_key(.pkcs8, primitive, fixture.name, true, [.sign], '') {
		assert false
	} else {
		assert err.msg() == 'DataError: ASN1::Decoder: Entering a non-constructed type'
	}
	short_key := subtle.import_key(.raw_public, [u8(1)], fixture.name, true, [.verify], '')!
	if _ := subtle.verify(fixture.name, short_key, [], []) {
		assert false
	} else {
		assert err.msg() == 'OperationError: Failed to verify message'
	}
}

@[heap]
struct MldsaBindingHost {
mut:
	work   []fn ()
	settle []fn ()
}

fn test_mldsa_promise_copies_context_and_message_before_crypto_settlement() {
	mut host := &MldsaBindingHost{}
	binding := SubtleCryptoBinding.create(SubtleCrypto.create(), webidl.PromiseContext{}, fn [mut host] (task fn ()) {
		host.work << task
	}, fn [mut host] (task fn ()) { host.settle << task })
	fixture := mldsa_source_fixtures[1]
	private_key := SubtleCrypto.create().import_key(.pkcs8, hex.decode(fixture.pkcs8_hex)!, fixture.name, true, [.sign], '')!
	public_key := SubtleCrypto.create().import_key(.spki, hex.decode(fixture.spki_hex)!, fixture.name, true, [.verify], '')!
	mut context := webidl.BufferSource.array_buffer('foo'.bytes())
	mut message := webidl.BufferSource.array_buffer('message'.bytes())
	algorithm := webidl.object_value({
		'name':    webidl.string_value(fixture.name)
		'context': webidl.buffer_source_value(context)
	})
	promise := binding.sign(algorithm, private_key, message)
	context.write('bar'.bytes(), 0)!
	message.write([u8(0)], 0)!
	assert promise.state == .pending
	host.work[0]()
	assert promise.state == .pending && host.settle.len == 1
	host.settle[0]()
	assert promise.state == .fulfilled
	signature := promise.result.buffer_value or { panic('signature') }
	assert SubtleCrypto.create().verify(Ed448Params{ name: fixture.name, context: 'foo'.bytes() }, public_key, webidl.get_buffer_source_copy(signature), 'message'.bytes())!
	assert !SubtleCrypto.create().verify(fixture.name, public_key, webidl.get_buffer_source_copy(signature), 'message'.bytes())!
}
